import{_ as a,o as t,c as s,ag as n}from"./chunks/framework.BSsJcWLc.js";const m=JSON.parse('{"title":"Data Layer","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/data-layer.md","filePath":"architecture/data-layer.md"}'),i={name:"architecture/data-layer.md"};function r(o,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="data-layer" tabindex="-1">Data Layer <a class="header-anchor" href="#data-layer" aria-label="Permalink to &quot;Data Layer&quot;">​</a></h1><p>Receives LSL streams, writes raw samples to shared memory ring buffers for zero-copy distribution, and saves data to HDF5 for persistence and offline analysis.</p><hr><h2 id="data-acquisition" tabindex="-1">Data Acquisition <a class="header-anchor" href="#data-acquisition" aria-label="Permalink to &quot;Data Acquisition&quot;">​</a></h2><p>DataAcquisition (<code>src/dendrite/data/acquisition.py</code>) connects to configured LSL streams, writes samples to shared ring buffers, and forwards events to the event queue for DataSaver persistence.</p><p>Dedicated reader threads per stream type pull samples at native rates, writing directly to a <code>SharedRingBuffer</code> with markers in the last column. LSL inlets use <code>proc_clocksync</code> and <code>proc_dejitter</code> for clock correction and jitter smoothing.</p><p>At least one numerical data stream (non-Events) is required for acquisition to start.</p><p><strong>Stream Types:</strong></p><table tabindex="0"><thead><tr><th>LSL Stream Type</th><th>Format</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>EEG</strong></td><td>Numeric</td><td>Neural signals</td></tr><tr><td><strong>EMG</strong></td><td>Numeric</td><td>Muscle signals</td></tr><tr><td><strong>EOG</strong></td><td>Numeric</td><td>Eye movement signals</td></tr><tr><td><strong>ContinuousEvents</strong></td><td>Numeric</td><td>Continuous position/torque data</td></tr><tr><td><strong>Events</strong></td><td>String (JSON)</td><td>Discrete task events (see <strong><a href="/dendrite/guides/send-events.html">Send Events</a></strong>)</td></tr><tr><td><strong>...</strong></td><td>Numeric/String</td><td>User-defined types (numerical: forwarded; string: saved only)</td></tr></tbody></table><p>Multiple streams of the same type are supported. Each gets a unique <code>stream_key</code> for pipeline indexing: the first stream of a type gets the type as key (e.g. <code>&quot;EEG&quot;</code>), duplicates get <code>&quot;EEG_2&quot;</code>, <code>&quot;EEG_3&quot;</code>, etc.</p><p>Stream types come from the LSL <code>type()</code> field. Only <strong>Events</strong> streams have special behavior (JSON parsing; event IDs injected into the markers column). Numerical streams are written to ring buffers at native rates. String streams are saved to disk only.</p><p><strong>Channel Types:</strong></p><p>Channel types are user-defined labels classifying individual channels by modality. A single LSL stream can contain mixed channel types (e.g., an EEG stream with 62 EEG channels, 2 EOG channels, and 1 Markers channel). Common types: EEG, EMG, EOG, Markers, Reference.</p><h3 id="markers-column" tabindex="-1">Markers Column <a class="header-anchor" href="#markers-column" aria-label="Permalink to &quot;Markers Column&quot;">​</a></h3><p><strong>Creation:</strong> The orchestrator creates each ring buffer with <code>raw_channels + 1</code> columns. The last column is the markers column (initialized to zero), invisible to stream configs.</p><p><strong>Event injection:</strong> DAQ&#39;s <code>_events_reader()</code> broadcasts each <code>event_id</code> to per-stream deques. Each reader thread pops from its deque and writes the event code into the markers column, keeping markers synchronized across all ring buffers. <strong>Event codes must be positive integers (&gt; 0) for real-time detection.</strong> The markers column uses <code>0.0</code> as the &quot;no event&quot; sentinel, so code 0 is indistinguishable from no event. Modes filter on <code>markers &gt; 0</code>; visualization skips <code>marker == 0</code>. Events with code 0 or negative codes are still saved to HDF5 via the separate event queue (and available for offline analysis), but are invisible to real-time modes and visualization. The MOABB loader auto-shifts codes if any would be 0.</p><p><strong>Persistence boundary:</strong> The markers column exists only in the ring buffer — DataSaver does not write it to HDF5. Events are persisted separately in the Event dataset with their original LSL timestamps, which are more accurate for offline epoch extraction than the marker injection point (up to 1 sample delayed). Modes use the marker column for real-time detection; offline loading uses the Event dataset.</p><p>See <strong><a href="/dendrite/guides/synchronous-mode.html">Synchronous Mode</a></strong> for epoch triggering and <strong><a href="/dendrite/guides/send-events.html">Send Events</a></strong> for event broadcasting.</p><h3 id="timestamp-types-and-semantics" tabindex="-1">Timestamp Types and Semantics <a class="header-anchor" href="#timestamp-types-and-semantics" aria-label="Permalink to &quot;Timestamp Types and Semantics&quot;">​</a></h3><p>Multiple timestamps captured at different pipeline stages:</p><table tabindex="0"><thead><tr><th>Timestamp</th><th>Source</th><th>Layer</th><th>Purpose</th></tr></thead><tbody><tr><td><code>timestamp</code> / <code>lsl_timestamp</code></td><td><code>inlet.pull_sample()</code></td><td>Data/Processing</td><td>LSL-synchronized capture time</td></tr><tr><td><code>local_timestamp</code></td><td><code>local_clock()</code></td><td>Data/Storage</td><td>Local machine receive time (LSL clock domain)</td></tr><tr><td><code>receive_timestamp</code></td><td><code>time.time()</code></td><td>Storage</td><td>Wall-clock receive time (system clock domain)</td></tr></tbody></table><p><strong>Internal timing (not persisted):</strong> <code>_receive_ns</code> (nanosecond pipeline latency tracking via <code>time.time_ns()</code>) and <code>data_timestamp</code> (copy of <code>lsl_timestamp</code> forwarded in mode output for end-to-end latency).</p><h3 id="latency-stream-health" tabindex="-1">Latency &amp; Stream Health <a class="header-anchor" href="#latency-stream-health" aria-label="Permalink to &quot;Latency &amp; Stream Health&quot;">​</a></h3><p><strong>LSL transmission latency</strong> (<code>local_timestamp - timestamp</code>): 2-10ms typical, warns if &gt;50ms. Each sample has independent delay. Per-stream metrics (rolling P50 latency, last update) published to SharedState for telemetry.</p><p><strong>Stream drops</strong>: Stream threads operate independently. Dropped streams hold last value while others continue. TelemetryWidget shows &quot;DROPPED&quot; after timeout. Saved files show drops as timestamp gaps. Streams reconnect automatically when source resumes.</p><h3 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h3><p>DAQ writes each sample as a flat float32 row <code>[raw_channels..., marker]</code> to the ring buffer. Consumers use the channel map to slice modality data. Events flow separately through <code>event_queue</code> as <code>EventRecord</code> objects to DataSaver.</p><p>Source: <code>src/dendrite/data/stream_schemas.py</code> (StreamMetadata), <code>src/dendrite/data/acquisition.py</code> (EventRecord)</p><hr><h2 id="shared-ring-buffer" tabindex="-1">Shared Ring Buffer <a class="header-anchor" href="#shared-ring-buffer" aria-label="Permalink to &quot;Shared Ring Buffer&quot;">​</a></h2><p>SharedRingBuffer (<code>src/dendrite/data/shared_buffers.py</code>) is a lock-free SPMC ring buffer backed by <code>multiprocessing.shared_memory</code>.</p><p>One ring buffer per numerical stream (keyed by <code>stream_key</code>). DAQ writes; all consumers connect and read independently with zero-copy access.</p><p><strong>Memory Layout:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Header 64B][Data float32 (max_samples × n_channels)][LSL_ts float64 (max_samples)][Local_ts float64 (max_samples)][Receive_ns uint64 (max_samples)]</span></span></code></pre></div><p>Header stores: write position (u64), channel count (u32), max samples (u32), sample rate (f64). Three timestamp arrays alongside data: LSL-synchronized, local clock, and wall-clock receive (nanoseconds).</p><p>Default buffer duration is 30 seconds (configurable via <code>compute_max_samples()</code>). At 500Hz with 65 channels, a buffer uses ~4MB of shared memory.</p><p>Buffer names derive from <code>stream_key</code>: <code>dendrite_rb_{stream_key.lower()}</code>. All consumers unpack <code>read_new()</code> the same way:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data, lsl_ts, local_ts, receive_ns, new_pos </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rb.read_new(last_read_pos)</span></span></code></pre></div><p>Returns all samples written since <code>last_read_pos</code>. If the reader falls too far behind, <code>OverrunError</code> is raised.</p><p>Source: <code>src/dendrite/data/shared_buffers.py</code></p><h3 id="channel-map" tabindex="-1">Channel Map <a class="header-anchor" href="#channel-map" aria-label="Permalink to &quot;Channel Map&quot;">​</a></h3><p>The orchestrator builds a channel map per ring buffer:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;buffer_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dendrite_rb_eeg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># derived from stream_key</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;modalities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eeg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">61</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eog&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">62</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">63</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]},  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># column indices by channel type</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;modality_labels&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eeg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Fp1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eog&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;VEOG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HEOG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;marker_col&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;sample_rate&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="datasaver" tabindex="-1">DataSaver <a class="header-anchor" href="#datasaver" aria-label="Permalink to &quot;DataSaver&quot;">​</a></h2><p>DataSaver (<code>src/dendrite/data/storage/data_saver.py</code>) is the single HDF5 writer for both archival and online training. Runs as a separate process, reads from shared ring buffers, and writes chunked structured datasets to disk.</p><p>Drains new samples every poll cycle, buffers in memory, and writes chunks to HDF5. Only modality channels are saved -- the markers column is excluded. Events arrive via <code>event_queue</code> from DAQ as <code>EventRecord</code> objects. Flushes every 2s for crash resistance.</p><p><strong>SWMR</strong> mode is enabled after the first flush, allowing MLService to read epochs concurrently during live recording.</p><p><strong>File Structure:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;file_identifier&gt;_raw.h5</span></span>
<span class="line"><span>├── EEG                 # Structured dataset: [Fp1 f32, Fp2 f32, ..., timestamp f64, local_timestamp f64, receive_timestamp f64]</span></span>
<span class="line"><span>├── EEG_2               # Second EEG stream (if present, keyed by stream_key)</span></span>
<span class="line"><span>├── EMG                 # Structured dataset (if present)</span></span>
<span class="line"><span>├── Event               # Compound dataset: [event_id i32, event_type str, timestamp f64, local_timestamp f64, receive_timestamp f64, extra_vars str]</span></span>
<span class="line"><span>└── &lt;OtherStreams&gt;      # Additional datasets as configured</span></span>
<span class="line"><span>attrs: created_timestamp, created_by, version, schema_version, study_name, ...,</span></span>
<span class="line"><span>       stream_index (JSON: {&quot;EEG&quot;: &quot;EEG&quot;, &quot;EEG_2&quot;: &quot;EEG&quot;, &quot;EMG&quot;: &quot;EMG&quot;})</span></span></code></pre></div><p>Dataset names match the <code>stream_key</code>. The <code>stream_index</code> root attribute maps each dataset name to its stream type, enabling <code>find_dataset()</code> to locate datasets by type even when names are disambiguated.</p><p>Timeseries datasets use NumPy structured arrays (one float32 per channel + three float64 timestamps). Dataset attrs preserve stream metadata for downstream channel type resolution. Events store the full event dict as JSON in <code>extra_vars</code>.</p><hr><h2 id="metricssaver" tabindex="-1">MetricsSaver <a class="header-anchor" href="#metricssaver" aria-label="Permalink to &quot;MetricsSaver&quot;">​</a></h2><p>MetricsSaver (<code>src/dendrite/data/storage/metrics_saver.py</code>) persists mode outputs (predictions, confidences, timing) to a separate HDF5 file.</p><p>Consumes output records from modes via <code>shared_metrics_queue</code>, creating one HDF5 group per mode. Datasets are created dynamically from mode output. Each metric gets a parallel <code>{metric}_timestamps</code> dataset.</p><p><strong>File Structure:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;session&gt;_metrics.h5</span></span>
<span class="line"><span>├── &lt;mode_name&gt;/               # e.g., &quot;sync_mode_0&quot;, &quot;async_mode_0&quot;</span></span>
<span class="line"><span>│   ├── &lt;metric_key&gt;           # Dynamic from mode output (predictions, confidences, etc.)</span></span>
<span class="line"><span>│   ├── &lt;metric_key&gt;_timestamps # Float64 epoch timestamps for temporal alignment</span></span>
<span class="line"><span>│   └── ...                    # Additional metrics as emitted by mode</span></span></code></pre></div><p><strong>Usage:</strong> Metrics file path registered in recordings table, linking mode outputs to source session.</p><hr><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><p>Database (<code>src/dendrite/data/storage/database.py</code>) tracks experiment lineage and recording metadata via SQLite at <code>data/dendrite.db</code>.</p><p>Four tables: <code>studies</code> (organization), <code>recordings</code> (session metadata, file paths, BIDS fields), <code>decoders</code> (trained model metadata, accuracy), <code>training_jobs</code> (async training status/results). Repository pattern with parameterized queries.</p><p>PipelineService registers sessions at pipeline start; ML workbench registers trained models; Data Explorer provides a browse interface.</p><h2 id="data-dimension-standard" tabindex="-1">Data Dimension Standard <a class="header-anchor" href="#data-dimension-standard" aria-label="Permalink to &quot;Data Dimension Standard&quot;">​</a></h2><p><strong>(channels, times)</strong> format throughout the pipeline:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ring Buffer:    DAQ writes flat rows → (n_channels,) per sample</span></span>
<span class="line"><span>                ↓ Modes slice by channel map</span></span>
<span class="line"><span>Mode Input:     Per-sample dicts with (n_channels, 1) arrays</span></span>
<span class="line"><span>                ↓ Buffer accumulates</span></span>
<span class="line"><span>Mode Buffers:   [(n_channels, 1), (n_channels, 1), ...]</span></span>
<span class="line"><span>                ↓ Direct concatenation along time axis</span></span>
<span class="line"><span>Mode Output:    np.concatenate(axis=1) → (n_channels, n_times)</span></span>
<span class="line"><span>                ↓ Add batch dimension in decoder</span></span>
<span class="line"><span>Decoder Input:  (batch, n_channels, n_times)</span></span>
<span class="line"><span>                ↓ Model-specific transforms (STFT, etc.)</span></span>
<span class="line"><span>Model Input:    • Time-series: (batch, 1, n_channels, n_times)</span></span>
<span class="line"><span>                • Time-frequency: (batch, n_channels, n_frequencies, n_times)</span></span></code></pre></div><hr><h2 id="file-loaders" tabindex="-1">File Loaders <a class="header-anchor" href="#file-loaders" aria-label="Permalink to &quot;File Loaders&quot;">​</a></h2><p>Three loaders (<code>src/dendrite/data/loaders/</code>) read offline data into <code>RawData</code> format: <strong>RawH5Loader</strong> (<code>.h5</code>), <strong>FIFLoader</strong> (<code>.fif</code>), and <strong>MOABBLoader</strong> (MOABB public datasets). All return <code>RawData</code> with data in (channels, samples) format, lowercase channel types, and sample-indexed events.</p><p><code>RawH5Loader</code> uses <code>find_dataset()</code> to locate data datasets by type via the <code>stream_index</code> attribute. Events are recovered from the Event dataset using <code>np.searchsorted</code> for sub-sample precision. HDF5 stores (samples, channels); loaders transpose on read.</p><p>MNE interop: <code>to_mne_raw()</code> on RawData, or <code>to_mne_raw()</code>/<code>export_to_fif()</code> directly from H5 files. Event metadata preserved via JSON in <code>raw.info[&#39;description&#39;]</code>.</p><p>Source: <code>src/dendrite/data/loaders/_types.py</code> (RawData, EpochedData), <code>src/dendrite/data/io/</code> (H5 explorer, MNE export)</p><h3 id="training-data-pipeline" tabindex="-1">Training Data Pipeline <a class="header-anchor" href="#training-data-pipeline" aria-label="Permalink to &quot;Training Data Pipeline&quot;">​</a></h3><p><code>load_moabb_for_training()</code> and <code>load_epochs()</code> compose loaders with epoching and preprocessing. Both apply configurable bandpass/CAR and reject bad epochs (NaN, flat, outlier). <code>load_epochs()</code> supports SWMR HDF5 reads for online training during live recording.</p><p>Source: <code>src/dendrite/data/loaders/_training_data.py</code></p><hr><h2 id="channel-quality-monitoring" tabindex="-1">Channel Quality Monitoring <a class="header-anchor" href="#channel-quality-monitoring" aria-label="Permalink to &quot;Channel Quality Monitoring&quot;">​</a></h2><p><code>ChannelQualityMonitor</code> (<code>src/dendrite/data/quality.py</code>) detects bad channels using rolling-window (5s) iterative MAD refinement with hysteresis (2 of 3 evaluations must exceed threshold). Per-channel status (&quot;good&quot;/&quot;warning&quot;/&quot;bad&quot;) drives both the real-time quality display in the visualization bridge and the automatic interpolation pipeline.</p><hr><p><strong>Related Documentation:</strong></p><ul><li><strong><a href="/dendrite/guides/send-events.html">Send Events</a></strong> — Event creation and broadcasting</li><li><strong><a href="./processing-layer.html">Processing Layer</a></strong> — Real-time data processing workflows</li></ul>`,82)])])}const u=a(i,[["render",r]]);export{m as __pageData,u as default};
